import { useEffect, useRef } from 'react'

export type ViewMode = 'list' | 'preview'

type Props = {
  view: ViewMode
  onChange: (view: ViewMode) => void
}

const OPTIONS: { id: ViewMode; label: string }[] = [
  { id: 'list', label: 'List' },
  { id: 'preview', label: 'Preview' },
]

export function ViewToggle({ view, onChange }: Props) {
  return (
    <div className="view-toggle" role="group" aria-label="View">
      {OPTIONS.map((option) => (
        <ViewButton
          key={option.id}
          option={option}
          selected={view === option.id}
          onSelect={onChange}
        />
      ))}
    </div>
  )
}

type ButtonProps = {
  option: (typeof OPTIONS)[number]
  selected: boolean
  onSelect: (view: ViewMode) => void
}

function ViewButton({ option, selected, onSelect }: ButtonProps) {
  const ref = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    // Clear the previous highlight when the view changes so the next
    // paint is clean.
    el.classList.remove('is-active')
  }, [selected])

  return (
    <button
      ref={ref}
      type="button"
      className="view-btn"
      data-testid={`view-${option.id}`}
      aria-pressed={selected}
      onClick={() => onSelect(option.id)}
    >
      {option.label}
    </button>
  )
}
/**
 * Apply a visual state class after layout has had a chance to settle.
 * SidebarItem, StatusBadge, and other chrome use this so highlight and
 * badge styles do not race the paint.
 *
 * Keep the delay here, not copied into each component.
 */
export const VISUAL_CLASS_DELAY_MS = 40

export function deferVisualClass(
  el: HTMLElement | null,
  className: string,
  on: boolean,
): () => void {
  if (!el) return () => {}
  el.classList.remove(className)
  const timer = window.setTimeout(() => {
    if (on) {
      el.classList.add(className)
    }
  }, VISUAL_CLASS_DELAY_MS)
  return () => window.clearTimeout(timer)
}
import { useState } from 'react'
import { Sidebar } from './Sidebar'
import { SearchField } from './SearchField'
import { PriorityFilter } from './PriorityFilter'
import { SyncIndicator } from './SyncIndicator'
import { ViewToggle, type ViewMode } from './ViewToggle'
import { FOLDERS, folderLabel, type FolderId } from './folders'

export function App() {
  const [selected, setSelected] = useState<FolderId>('inbox')
  const [query, setQuery] = useState('')
  const [priorityOnly, setPriorityOnly] = useState(false)
  const [view, setView] = useState<ViewMode>('list')
  const current = FOLDERS.find((folder) => folder.id === selected)!

  return (
    <div className="app">
      <Sidebar selected={selected} onSelect={setSelected} />
      <main className="panel">
        <header className="toolbar">
          <SearchField value={query} onChange={setQuery} />
          <PriorityFilter
            active={priorityOnly}
            onToggle={() => setPriorityOnly((value) => !value)}
          />
          <ViewToggle view={view} onChange={setView} />
          <SyncIndicator online />
        </header>
        <h1>{folderLabel(selected)}</h1>
        <p>
          {current.unread === 0
            ? 'No unread messages.'
            : `${current.unread} unread in this folder.`}
        </p>
        <p className="view-copy" data-testid="view-copy">
          {view === 'list' ? 'Showing a list of messages.' : 'Showing the preview pane.'}
          {priorityOnly ? ' Priority messages only.' : ''}
          {query ? ` Filtered by “${query}”.` : ''}
        </p>
      </main>
    </div>
  )
}
